const FISH = new Set(['salmon', 'flatfish', 'tuna', 'eel']);
const at = (svg, x, y, a = 0, s = 1) => `<g transform="translate(${x} ${y}) rotate(${a}) scale(${s})">${svg}</g>`;
const LARGE = '<g transform="translate(80 12)"><rect x="-14" y="-7" width="28" height="14" rx="7" fill="#d9302a"/><text x="0" y="4" text-anchor="middle" font-size="9" font-weight="800" fill="#fff" font-family="sans-serif">LARGE</text></g>';
function body(p, bigLabel) {
    const [, bg, full, plain, slots, dflt] = B[p.base];
    const tops = p.with.length ? p.with : dflt;
    let svg;
    if (p.base === 'sushi' && tops.some(t => FISH.has(t))) {
        const fish = tops.filter(t => FISH.has(t)), sl = p.size === 'large' ? NIG_L : NIG;
        svg = (p.size === 'large' ? '<rect x="4" y="16" width="92" height="76" rx="8" fill="#2b2420"/><rect x="8" y="20" width="84" height="68" rx="6" fill="#3a302a"/>' : '<rect x="6" y="20" width="88" height="64" rx="8" fill="#2b2420"/><rect x="10" y="24" width="80" height="56" rx="6" fill="#3a302a"/>')
            + sl.map(([x, y], k) => at(`<rect x="-11" y="-5" width="22" height="16" rx="7" fill="#f6f3ea"/><path d="M-7 7 q7 3 14 0" stroke="#e8e2d6" stroke-width="1.4" fill="none" stroke-linecap="round"/>${at(T[fish[k % fish.length]], 0, -2)}`, x, y, 0, p.size === 'large' ? 0.9 : 1)).join('');
    } else if (tops.length && slots.length) {
        const n = ['sashimi', 'hoedeopbap', 'inari', 'maki'].includes(p.base) || tops.every(t => FISH.has(t)) ? slots.length : Math.min(slots.length, Math.max(2, tops.length * 2));
        svg = (plain || full) + slots.slice(0, n).map(([x, y], k) => at(T[tops[k % tops.length]], x, y, (k * 37) % 40 - 20, p.base === 'sashimi' ? 1 : 0.85)).join('');
    } else svg = full;
    if (p.size === 'large' && p.base !== 'sushi') svg = `<g transform="translate(50 52) scale(1.08) translate(-50 -52)">${svg}</g>`;
    if (p.size === 'large' && bigLabel) svg += LARGE.replace('LARGE', bigLabel);
    if (p.set.length) svg = `<g transform="translate(6 4) scale(.72)">${svg}</g>` + p.set.map((s, k) => at(S[s], 80, k ? 46 : 80, 0, 1.05)).join('');
    return [bg, svg];
}
// a dish picture: 'thumb' (square), 'hero' (the store's wide picture) or 'item' (a dish's picture), sized by its container
export function dishSvg(p, mode = 'thumb', bigLabel = '') {
    const pic = picOf(p) || guessPic('');
    const [bg, svg] = body(pic, bigLabel), [, , , , , , hero, item] = B[pic.base];
    const vb = mode === 'hero' ? hero.join(' ') : mode === 'item' ? item.join(' ') : '0 0 100 100';
    return `<svg viewBox="${vb}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect x="-200" y="-200" width="500" height="500" fill="${bg}"/>${svg}</svg>`;
}
